import math
from typing import List, Sequence

Vector = Sequence[float]

def nsq(x: Vector) -> float:
    return sum(v * v for v in x)

def K(q: Vector, k: Vector) -> float:
    return 1.0 / (1.0 + nsq([qi - ki for qi, ki in zip(q, k)]))

def P(x: Vector) -> List[float]:
    s = 2.0 / (1.0 + nsq(x))
    return [s * xi for xi in x]

def Hh(x: Vector) -> float:
    t = nsq(x)
    return (t - 1.0) / (t + 1.0)

for x in ([0.0, 0.0], [3.0, -4.0], [2.0, 1.0, -1.0]):
    on_sphere = nsq(P(x)) + Hh(x) ** 2
    chord = nsq(P(x)) + (Hh(x) - 1.0) ** 2
    assert abs(on_sphere - 1.0) < 1e-12
    assert abs(chord - 4.0 * K(x, [0.0] * len(x))) < 1e-12
    assert 0.0 < K(x, [0.0] * len(x)) <= 1.0
print('core identities verified')

