function STEREO_ATTENTION(q, keys[1..N], values[1..N]):
    for i in 1..N:
        d2     <- ||q - keys[i]||^2
        s[i]   <- 1 / (1 + d2)            # Cauchy kernel, in (0,1]
    Z <- sum(s[1..N])                      # Z > 0 since each s[i] > 0
    out <- 0
    for i in 1..N:
        out <- out + (s[i] / Z) * values[i]
    return out
